mapper.select:
SELECT template_id, template_name, template_code, data_id, group_id, content, type, database_type, description, create_user_id, create_user_name, update_time, create_time FROM t_nacos_config_template
AND template_name LIKE CONCAT('%', #{query.templateName}, '%')
AND template_code LIKE CONCAT('%', #{query.templateCode}, '%')
AND type = #{query.type}
AND database_type = #{query.databaseType}
ORDER BY create_time DESC
